const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = validators[message.type];
  if (validator) return validator(message);

  return {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const listSessions: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string | number; sessionId: string}} =
    {
      type: 'list_sessions',
    };

  if ('limit' in message) {
    const {limit} = message;
    if (typeof limit !== 'number' || !Number.isInteger(limit)) {
      return {valid: false, error: 'limit must be an integer between 1 and 200'};
    }
    if (limit <= 0 || limit > 200) {
      return {valid: false, error: 'limit must be an integer between 1 and 200'};
    }
    listSessions.limit = limit;
  }

  if ('before' in message) {
    const {before} = message;
    if (typeof before !== 'object' || before === null) {
      return {valid: false, error: 'before must be an object'};
    }
    const cursor = before as Record<string, unknown>;
    if (typeof cursor.sessionId !== 'string' || cursor.sessionId.length < 1 || cursor.sessionId.length > 128) {
      return {valid: false, error: 'before.sessionId must be 1-128 characters'};
    }
    if (typeof cursor.updatedAt !== 'string' && typeof cursor.updatedAt !== 'number') {
      return {valid: false, error: 'before.updatedAt must be a string or number'};
    }
    if (typeof cursor.updatedAt === 'string' && isNaN(Date.parse(cursor.updatedAt))) {
      return {valid: false, error: 'before.updatedAt must be a valid date string'};
    }
    if (typeof cursor.updatedAt === 'number' && !Number.isFinite(cursor.updatedAt)) {
      return {valid: false, error: 'before.updatedAt must be a finite number'};
    }
    listSessions.before = {
      sessionId: cursor.sessionId,
      updatedAt: cursor.updatedAt,
    };
  }

  return {valid: true, data: listSessions as IncomingMessage};
}

