import {PerSessionLock} from '../../shared/perSessionLock.js';
import {deferred} from '../wsTestSupport.js';

it('answers list_sessions for the authenticated user', async () => {
  const summaries = [
    {
      sessionId: 's2',
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-01T00:02:00.000Z'),
      entryCount: 2,
    },
  ];
  const sessionStore = {
    listFor: jest.fn<NonNullable<SessionStore['listFor']>>().mockResolvedValue(summaries),
  } as unknown as SessionStore;
  const orchestrator = {} as unknown as ChatOrchestrator;
  const options = {history: {enabled: true}};

  const handle = createMessageHandler(orchestrator, sessionStore, options);
  const sent: OutgoingMessage[] = [];
  const ws = {
    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
    userId: 'u1',
  } as unknown as WebSocket;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const before: SessionCursor = {sessionId: 's3', updatedAt: '2026-01-01T01:00:00Z'};

  await handle(ws, session, {
    type: 'list_sessions',
    limit: 10,
    before,
  });

  expect({sent, asked: (sessionStore.listFor as jest.Mock).mock.calls}).toEqual({
    asked: [['u1', {limit: 10, before}]],
    sent: [
      {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's2',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T00:02:00.000Z',
            entryCount: 2,
          },
        ],
      },
    ],
  });
});

